var ua = "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36";
var bases = ["https://se.btlm.one", "https://run.btlm.info", "https://cy.btlm.one"];

function clean(v) {
    return String(v || "")
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<style[\s\S]*?<\/style>/gi, "")
        .replace(/<[^>]+>/g, " " )
        .replace(/&nbsp;/gi, " " )
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#39;/gi, "'")
        .replace(/&quot;/gi, "\"")
        .replace(/\s+/g, " " )
        .replace(/^\s+|\s+$/g, "");
}

function origin(u) {
    var m = String(u || "").match(/^(https?:\/\/[^\/]+)/i);
    return m ? m[1] : "";
}

function abs(base, href) {
    href = String(href || "").replace(/&amp;/g, "&");
    if (!href) return "";
    if (/^https?:\/\//i.test(href)) return href;
    if (/^\/\//.test(href)) return "https:" + href;
    var o = origin(base);
    if (href.charAt(0) === "/") return o + href;
    return o + "/" + href.replace(/^\.\//, "");
}

function getHtml(url, ref) {
    return String(fetch(url, {
        headers: {
            "User-Agent": ua,
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.6",
            "Referer": ref || "https://mm.btlm.in/"
        },
        timeout: 5500
    }) || "");
}

function hashFrom(v) {
    v = String(v || "");
    var m = v.match(/btih:([A-Fa-f0-9]{40})/i);
    if (!m) m = v.match(/btih:([A-Za-z2-7]{32})/i);
    if (!m) m = v.match(/([A-Fa-f0-9]{40})/);
    return m ? String(m[1]).toUpperCase() : "";
}

function makeMagnet(h, title) {
    var u = "magnet:?xt=urn:btih:" + h;
    if (title) u += "&dn=" + encodeURIComponent(title);
    return u;
}

function sizeBytes(text) {
    var m = String(text || "").match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
    if (!m) return 0;
    var n = Number(m[1] || 0);
    var u = String(m[2] || "B").toUpperCase();
    var pow = 0;
    if (u === "KB") pow = 1;
    else if (u === "MB") pow = 2;
    else if (u === "GB") pow = 3;
    else if (u === "TB") pow = 4;
    return Math.round(n * Math.pow(1024, pow));
}

function parse(html, base) {
    var out = [];
    var seen = {};
    var re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    var m;
    var qLow = q.toLowerCase();
    while ((m = re.exec(html)) !== null) {
        var href = String(m[1] || "");
        var title = clean(m[2]);
        if (!title || title.length < 2) continue;
        if (title.toLowerCase().indexOf(qLow) < 0) continue;
        if (/^(首页|搜索|相关度|文件大小|下载次数|收录时间|下一页|上一页|在线播放|下载链接|磁力链接|更多)$/.test(title)) continue;
        var full = abs(base, href);
        if (!full && href.indexOf("magnet:?") !== 0) continue;

        var st = m.index - 300;
        if (st < 0) st = 0;
        var en = re.lastIndex + 1200;
        if (en > html.length) en = html.length;
        var near = clean(html.substring(st, en));

        var sm = near.match(/文件大小\s*[:：]?\s*([0-9.]+\s*(TB|GB|MB|KB|B))/i);
        var fm = near.match(/文件数量\s*[:：]?\s*(\d+)/i);
        var dm = near.match(/收录时间\s*[:：]?\s*([0-9]{2,4}[-\/.][0-9]{1,2}[-\/.][0-9]{1,2})/i);
        var hm = near.match(/热度\s*[:：]?\s*(\d+)/i);

        var h = hashFrom(href);
        var key = h || full || title;
        if (seen[key]) continue;
        seen[key] = 1;

        var desc = [];
        if (sm) desc.push(sm[1]);
        if (fm) desc.push(fm[1] + "个文件");
        if (hm) desc.push("热度" + hm[1]);

        var item = {
            title: title,
            bytes: sm ? sizeBytes(sm[1]) : 0,
            seeders: hm ? Number(hm[1]) : -1,
            peers: -1,
            date: dm ? dm[1] : "",
            desc: desc.join(" · ")
        };
        if (h) item.magnet = makeMagnet(h, title);
        else if (href.indexOf("magnet:?") === 0) item.magnet = href.replace(/&amp;/g, "&");
        else item.url = full;
        out.push(item);
    }
    return out;
}

var errors = [];
for (var i = 0; i < bases.length; i++) {
    var base = bases[i];
    try {
        var url = base + "/search?keyword=" + encodeURIComponent(q);
        if (p > 1) url += "&page=" + p;
        var html = getHtml(url, base + "/");
        if (!html) throw new Error("空响应");
        if (/captcha|cloudflare|access denied|forbidden|recaptcha|challenge/i.test(html)) throw new Error("触发网页验证");
        var items = parse(html, base);
        if (items.length) return items;
        var t = clean(html);
        var cm = t.match(/搜索结果\s*([0-9,]+)\s*条/);
        if (cm && Number(String(cm[1]).replace(/,/g, "")) === 0) return [];
        errors.push(base + "：页面有响应但未解析到标题链接");
    } catch (e) {
        errors.push(base + "：" + String(e.message || e));
    }
}
throw new Error("BT联盟搜索失败；" + errors.join("；"));

